const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.geometry.Point([49.357405, 39.014501]).buffer(4000);
  const dateBefore = ee.DateRange('2022-11-16', '2022-11-22');
  const dateAfter = ee.DateRange('2023-02-10', '2023-02-16');

  // 2. Data Acquisition & Processing Function
  function getLandPixels(dateRange) {
    const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(dateRange)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const size = s2.size().getInfo();
    if (size === 0) {
      return { 'image': null, 'size': 0 };
    }

    const image = s2.median(); // Use median to reduce noise/clouds

    // Function to mask clouds using the QA60 band
    function maskS2clouds(img) {
      const qa = img.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return img.updateMask(mask).divide(10000);
    }

    const maskedImage = maskS2clouds(image);

    // Calculate NDWI = (Green - NIR) / (Green + NIR)
    // Sentinel-2 bands: B3 = Green, B8 = NIR
    const ndwi = maskedImage.normalizedDifference(['B3', 'B8']).rename('ndwi');

    // Land is typically NDWI <= 0. Water is NDWI > 0.
    const land = ndwi.lte(0);
    return { 'image': land, 'size': size };
  }

  // 3. Process data for both periods
  const beforeData = getLandPixels(dateBefore);
  const afterData = getLandPixels(dateAfter);

  console.log(`Images found for Nov 2022 period: ${beforeData.size}`);
  console.log(`Images found for Feb 2023 period: ${afterData.size}`);

  if (beforeData.size === 0 || afterData.size === 0) {
    console.log("Evidence: No cloud-free images found for one or both periods.");
    console.log("A"); // The island did appear, this is not a data failure
  }

  const landImageBefore = beforeData.image;
  const landImageAfter = afterData.image;

  // 4. Calculation & Validation
  const scale = 30; // Scale for Sentinel-2 processing

  const landPixelsBeforeStats = landImageBefore.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const landPixelsAfterStats = landImageAfter.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  // Use .evaluate to handle potential async issues and get results
  const beforeResult = await new Promise((resolve, reject) => landPixelsBeforeStats.evaluate(resolve, reject));
  const afterResult = await new Promise((resolve, reject) => landPixelsAfterStats.evaluate(resolve, reject));

  const landCountBefore = beforeResult['ndwi_sum'];
  const totalPixelsBefore = beforeResult['ndwi_count'];
  const landCountAfter = afterResult['ndwi_sum'];
  const totalPixelsAfter = afterResult['ndwi_count'];

  if (totalPixelsBefore === 0 || totalPixelsAfter === 0) {
      console.log("Evidence: After cloud masking, no valid pixels remained in the AOI for at least one date.");
      console.log(`Valid Pixels (Nov 2022): ${totalPixelsBefore}`);
      console.log(`Valid Pixels (Feb 2023): ${totalPixelsAfter}`);
      console.log("C2");
      return;
  }

  if (landCountBefore == null || landCountAfter == null) {
      console.log("Evidence: Calculation of land pixels returned a null value.");
      console.log("C3");
      return;
  }

  const landAreaBefore_m2 = landCountBefore * scale * scale;
  const landAreaAfter_m2 = landCountAfter * scale * scale;

  console.log(`Evidence (Nov 2022): Identified land pixels: ${landCountBefore} (~${(landAreaBefore_m2 / 1000000).toFixed(2)} sq km)`);
  console.log(`Evidence (Feb 2023): Identified land pixels: ${landCountAfter} (~${(landAreaAfter_m2 / 1000000).toFixed(2)} sq km)`);

  // Condition: Island exists if there is a significant amount of new land.
  // We check that land 'before' is minimal (e.g., < 1 sq km) and 'after' is substantial (> 1 sq km).
  const islandAppeared = landAreaBefore_m2 < 1000000 && landAreaAfter_m2 > 1000000;

  if (islandAppeared) {
    console.log("Conclusion: A new landmass appeared between the two dates.");
    console.log("A");
  } else {
    console.log("Conclusion: No new significant landmass appeared.");
    console.log("B");
  }

}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
